func sourceRoot(t *testing.T) string {
	t.Helper()
	path, err := runfiles.Rlocation("yomux/static_src/build-manifest.json")
	if err != nil {
		t.Fatal(err)
	}
	return filepath.Dir(filepath.Dir(path))
}

// The fixture records independently generated bytes from the previous builder,
// including every locale and its protected pseudo-locale tokens.
func TestFixedAssetContract(t *testing.T) {
	root := sourceRoot(t)
	outputs, err := Build(root)
	if err != nil {
		t.Fatal(err)
	}
	var contract struct {
		Baseline            map[string]string `json:"baseline"`
		SHA256              map[string]string `json:"sha256"`
		ReviewedTextChanges map[string][]struct {
			Baseline string `json:"baseline"`
			Current  string `json:"current"`
		} `json:"reviewed_text_changes"`
	}
	if err := readJSON(filepath.Join(root, "tests", "fixtures", "static_assets_contract.json"), &contract); err != nil {
		t.Fatal(err)
	}
	expected := contract.SHA256
	if len(contract.Baseline["source_commit"]) != 40 || len(contract.Baseline["builder_blob"]) != 40 {
		t.Fatal("missing baseline provenance")
	}
	if len(outputs) != len(expected) {
		t.Fatalf("outputs=%d want %d", len(outputs), len(expected))
	}
	for name, digest := range expected {
		// Keep the independent baseline oracle across explicitly reviewed copy
		// changes. Every other byte must still match the original builder.
		baselineBytes := outputs[name]
		for _, change := range contract.ReviewedTextChanges[name] {
			if change.Baseline == "" || change.Current == "" || bytes.Count(baselineBytes, []byte(change.Current)) != 1 || bytes.Contains(baselineBytes, []byte(change.Baseline)) {
				t.Fatalf("%s reviewed text change is missing, duplicated, or already contains the retired copy", name)
			}
			baselineBytes = bytes.Replace(baselineBytes, []byte(change.Current), []byte(change.Baseline), 1)
		}
		actual := sha256.Sum256(baselineBytes)
		if hex.EncodeToString(actual[:]) != digest {
			t.Errorf("%s digest=%x want %s", name, actual, digest)
		}
	}
	destination := t.TempDir()
	changed, err := Publish(destination, outputs, false)
	if err != nil || len(changed) != len(expected) {
		t.Fatalf("publication: %v %v", changed, err)
	}
	unchanged, err := Publish(destination, outputs, true)
	if err != nil || len(unchanged) != 0 {
		t.Fatalf("check: %v %v", unchanged, err)
	}
	path := filepath.Join(destination, "yomux.js")
	if err := os.WriteFile(path, []byte("stale"), 0o640); err != nil {
		t.Fatal(err)
	}
	stale, err := Publish(destination, outputs, true)
	if err != nil || len(stale) != 1 || stale[0] != "yomux.js" {
		t.Fatalf("stale check: %v %v", stale, err)
	}
	info, err := os.Stat(path)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := Publish(destination, outputs, false); err != nil {
		t.Fatal(err)
	}
	after, err := os.Stat(path)
	if err != nil || after.Mode().Perm() != info.Mode().Perm() {
		t.Fatalf("mode changed: %v %v", after, err)
	}
}

func TestPseudoTokensAndUnicode(t *testing.T) {
	p, err := loadPseudo(sourceRoot(t))
	if err != nil {
		t.Fatal(err)
	}
	for input, expected := range map[string]string{
		"éCtrl-A é":     "⟦éÇťřł-Á é····⟧",
		"":              "⟦·⟧",
		"Hello {name}!": "⟦Ĥéłłó {name}!···⟧",
		"{count:d} `code` https://a.example/x /static/x.js <b> ~/a Ctrl-A Cmd+K": "⟦{count:d} `code` https://a.example/x /static/x.js <b> ~/a Ctrl-A Cmd+K···⟧",
	} {
		if actual := p.pseudo(input); actual != expected {
			t.Errorf("pseudo(%q)=%q want %q", input, actual, expected)
		}
	}
}

func TestPublishRejectsEscape(t *testing.T) {
	if _, err := Publish(t.TempDir(), map[string][]byte{"../outside": []byte("x")}, false); err == nil {
		t.Fatal("accepted escaping output")
	}
}

func TestBuildRejectsCorruptSourceBeforePublication(t *testing.T) {
	for _, scenario := range []string{"unbalanced-css", "lost-placeholder", "lost-protected-token", "blank-translation", "null-translation"} {
		t.Run(scenario, func(t *testing.T) {
			root := t.TempDir()
			write := func(name, text string) {
				t.Helper()
				path := filepath.Join(root, name)
				if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(path, []byte(text), 0o600); err != nil {
					t.Fatal(err)
				}
			}
			write("static_src/build-manifest.json", `{"app.css":["static_src/app.css"]}`)
			write("static_src/app.css", `.x { content: "}"; /* { */ color: red; }`)
			write("assets/runtime/locale-registry.json", `[{"code":"en","plural_categories":["one","other"]},{"code":"es","plural_categories":["one","other"]}]`)
			write("static_src/locales/en.json", `{"hello":"Hello {name} `+"`code`"+`"}`)
			write("static_src/locales/es.json", `{"hello":"Hola {name} `+"`code`"+`"}`)
			spec, err := os.ReadFile(filepath.Join(sourceRoot(t), "static_src/pseudo-locale.json"))
			if err != nil {
				t.Fatal(err)
			}
			write("static_src/pseudo-locale.json", string(spec))
			if _, err := Build(root); err != nil {
				t.Fatalf("valid fixture: %v", err)
			}
			switch scenario {
			case "unbalanced-css":
				write("static_src/app.css", `.x {`)
			case "lost-placeholder":
				write("static_src/locales/es.json", `{"hello":"Hola `+"`code`"+`"}`)
			case "lost-protected-token":
				write("static_src/locales/es.json", `{"hello":"Hola {name}"}`)
			case "blank-translation":
				write("static_src/locales/es.json", `{"hello":""}`)
			case "null-translation":
				write("static_src/locales/es.json", `{"hello":null}`)
			}
			if _, err := Build(root); err == nil {
				t.Fatal("accepted corrupt source")
			}
		})
	}
}

func TestCatalogSeparatorsDoNotCorruptLiteralEscapes(t *testing.T) {
	catalog := map[string]string{"literal": `\u2028`, "separator": "\u2028\u2029"}
	encoded, err := catalogJSON(catalog)
	if err != nil {
		t.Fatal(err)
	}
	var actual map[string]string
	if err := json.Unmarshal(encoded, &actual); err != nil {
		t.Fatalf("invalid JSON: %s: %v", encoded, err)
	}
	for key, value := range catalog {
		if actual[key] != value {
			t.Errorf("%s=%q want %q", key, actual[key], value)
		}
	}
}

func TestPublishRejectsDescendantSymlinksBeforeAnyWrite(t *testing.T) {
	root, foreign := t.TempDir(), t.TempDir()
	if err := os.Symlink(foreign, filepath.Join(root, "locales")); err != nil {
		t.Fatal(err)
	}
	outputs := map[string][]byte{"first.js": []byte("first"), "locales/en.json": []byte("{}")}
	if _, err := Publish(root, outputs, false); err == nil {
		t.Fatal("accepted descendant symlink")
	}
	for _, path := range []string{filepath.Join(root, "first.js"), filepath.Join(foreign, "en.json")} {
		if _, err := os.Stat(path); !os.IsNotExist(err) {
			t.Fatalf("refusal wrote %s: %v", path, err)
		}
	}
}

func TestPseudoUnicodeBoundaryContract(t *testing.T) {
	root := sourceRoot(t)
	var cases []struct {
		Input     string         `json:"input"`
		Output    string         `json:"output"`
		Protected map[string]int `json:"protected"`
	}
	if err := readJSON(filepath.Join(root, "tests/fixtures/static_pseudo_contract.json"), &cases); err != nil {
		t.Fatal(err)
	}
	p, err := loadPseudo(root)
	if err != nil {
		t.Fatal(err)
	}
	if len(cases) != 120 {
		t.Fatalf("case count=%d want 120", len(cases))
	}
	for _, example := range cases {
		if output := p.pseudo(example.Input); output != example.Output {
			t.Errorf("pseudo(%q)=%q want %q", example.Input, output, example.Output)
		}
		if actual := tokenCounts(p.protected, example.Input, false); !sameCounts(actual, example.Protected) {
			t.Errorf("protected(%q)=%v want %v", example.Input, actual, example.Protected)
		}
	}
}
